-- Quatre pages historiques employaient des interpolations dont les fonctions ne
-- modifiaient pas le rendu. Elles utilisent désormais un fragment complet et exact.
update public.scolarite_content_fragments set text_value = case fragment_key
  when 'f00028' then 'Le meurtre (article 221-3 al. 1 C.P.) : le meurtre est alors qualifié d’assassinat.'
  when 'f00030' then 'L’empoisonnement (article 221-5 al. 3 C.P.).'
  when 'f00031' then 'Les tortures ou actes de barbarie (article 222-3, 9° C.P.).'
  when 'f00032' then 'Les violences (articles 222-8, 222-10, 222-12, 222-13, 9° et 222-14-5 C.P.).'
end, is_runtime_connected = true
where source_path in (
  'lib/content/gpx_scolarite/dps_dpg/sanction_pages/causes_aggravation_sanction/guet_apens_page.dart',
  'lib/content/pa_scolarite/sanction_pages/causes_aggravation_sanction/guet_apens_page.dart'
) and fragment_key in ('f00028','f00030','f00031','f00032');

update public.scolarite_content_fragments set text_value = case fragment_key
  when 'f00079' then 'Évasion : peines cumulatives. (article 434-31 du Code pénal)'
  when 'f00080' then 'Rébellion de prisonniers : peine cumulée avec celle subie. (article 433-9 du Code pénal)'
  when 'f00081' then 'Usurpation d’identité : cumul avec l’infraction à l’occasion de laquelle elle est commise. (article 434-23 du Code pénal)'
  when 'f00082' then 'Organisation frauduleuse d’insolvabilité : possibilité de non-confusion. (article 314-8 alinéa 2 du Code pénal)'
  when 'f00083' then 'Refus d’obtempérer : cumul avec les infractions commises à l’occasion de la conduite. (article L. 233-1 II du Code de la route)'
  when 'f00084' then 'Infractions graves commises en détention : cumul sans confusion possible. (article 132-6-1 du Code pénal — infractions articles 706-73 et 706-73-1 du Code de procédure pénale)'
end, is_runtime_connected = true
where source_path in (
  'lib/content/gpx_scolarite/dps_dpg/sanction_pages/pluralite_infractions/concours_reel_infractions_page.dart',
  'lib/content/pa_scolarite/sanction_pages/pluralite_infractions/concours_reel_infractions_page.dart'
) and fragment_key in ('f00079','f00080','f00081','f00082','f00083','f00084');

create or replace function public.scolarite_admin_get_editor(p_source_path text)
returns jsonb language plpgsql security definer
set search_path = pg_catalog, public
as $$
declare v_link jsonb; v_linked_source text; v_track text; v_fragments jsonb;
begin
  perform public.quiz_admin_guard();
  select track into v_track from public.scolarite_source_registry where source_path=p_source_path;
  if v_track is null then raise exception 'Source introuvable.' using errcode='22023'; end if;

  select to_jsonb(l),
    case when l.gpx_source_path=p_source_path then l.pa_source_path else l.gpx_source_path end
  into v_link, v_linked_source
  from public.scolarite_content_links l
  where l.gpx_source_path=p_source_path or l.pa_source_path=p_source_path;

  select coalesce(jsonb_agg(to_jsonb(f) order by f.position), '[]'::jsonb)
  into v_fragments from public.scolarite_content_fragments f
  where f.source_path=p_source_path and f.is_runtime_connected;

  return jsonb_build_object(
    'source_path', p_source_path,
    'track', v_track,
    'fragments', v_fragments,
    'link', v_link,
    'linked_source_path', v_linked_source
  );
end;
$$;
revoke all on function public.scolarite_admin_get_editor(text) from public, anon;
grant execute on function public.scolarite_admin_get_editor(text) to authenticated, service_role;

notify pgrst, 'reload schema';

